<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { Check, Clock, Connection, Document, Plus, Refresh, Search, Upload, Warning } from '@element-plus/icons-vue'
import NcLayout from '../components/NcLayout.vue'
import { ApiRequestError, cancelNetworkImport, confirmNetworkImport, createNetworkAddress, createNetworkImport, createNetworkMembership, createNetworkReview, createVlanPlan, dryRunNetworkImport, getAddressHistory, getDeviceAddresses, getDeviceInventory, getDeviceMemberships, getNetworkDiff, getNetworkDomains, getNetworkReviews, getP2B4Operations, getVlanHistory, getVlanPlans, type DeviceInventoryItem, type P2B3Address, type P2B3DiffFact, type P2B3DiffItem, type P2B3Domain, type P2B3Membership, type P2B3NetworkDiff, type P2B3VlanPlan, type P2B4History, type P2B4ImportStatus, type P2B4Operation, type P2B4Review, updateNetworkAddress, updateVlanPlan } from '../api/client'
import { useAuthStore } from '../stores/auth'

type PlanningTab = 'addresses' | 'domains' | 'vlans' | 'diff' | 'review-import' | 'operations'
const auth = useAuthStore()
const storageKey = 'netconsole.p2b5-planning-state'
const saved = loadState()
const activeTab = ref<PlanningTab>(saved.activeTab || 'addresses')
const selectedDeviceId = ref(saved.selectedDeviceId || '')
const search = ref(saved.search || '')
const domainFilter = ref(saved.domainFilter || '')
const sourceFilter = ref(saved.sourceFilter || '')
const resolutionFilter = ref(saved.resolutionFilter || '')
const readAvailable = ref(false)
const writeAvailable = ref(false)
const unavailableReason = ref('正在检查 Schema v13 / v14 隔离能力…')
const loading = ref(false)
const errorMessage = ref('')
const devices = ref<DeviceInventoryItem[]>([])
const domains = ref<P2B3Domain[]>([])
const addresses = ref<P2B3Address[]>([])
const memberships = ref<P2B3Membership[]>([])
const vlanPlans = ref<P2B3VlanPlan[]>([])
const diff = ref<P2B3NetworkDiff | null>(null)
const operations = ref<P2B4Operation[]>([])
const reviews = ref<P2B4Review[]>([])
const history = ref<P2B4History[]>([])
const historyTitle = ref('')
const historyLoading = ref(false)
const historyDialog = ref(false)
const addressCursor = ref<string | undefined>(undefined)
const vlanCursor = ref<string | undefined>(undefined)
const domainCursor = ref<string | undefined>(undefined)
const pageTotals = reactive({ addresses: 0, domains: 0, vlans: 0 })
const selectedDevice = computed(() => devices.value.find((item) => item.id === selectedDeviceId.value) || null)
const writeLabel = computed(() => writeAvailable.value ? '隔离写入已授权' : '当前只读')
const selectedDeviceLabel = computed(() => selectedDevice.value?.name || selectedDeviceId.value || '未选择设备')

const addressDialog = ref(false)
const vlanDialog = ref(false)
const membershipDialog = ref(false)
const addressForm = reactive({ id: '', deviceId: '', networkDomainId: '', addressFamily: 'IPv4', normalizedAddress: '', prefixLength: 24, addressRole: 'MANAGEMENT', sourceKind: 'PLANNED', sourceReference: '', interfaceReference: '', gatewayAddress: '', vrfName: '', validFromMs: '', validToMs: '', expectedRevision: 0 })
const vlanForm = reactive({ id: '', networkDomainId: '', vlanId: 100, name: '', purpose: '', taggingMode: 'ACCESS', nativeVlanId: '', pvid: '100', qinQOuterId: '', qinQInnerId: '', sourceKind: 'PLANNED', sourceReference: '', validFromMs: '', validToMs: '', expectedRevision: 0 })
const membershipForm = reactive({ networkDomainId: '', membershipRole: 'PRIMARY', sourceKind: 'PLANNED', sourceReference: '', validFromMs: '', validToMs: '' })
const reviewForm = reactive({ targetType: 'ADDRESS', targetId: '', sourceKind: 'PLANNED', sourceReference: '', targetRevision: 1, decision: 'ACCEPT_PLANNED', reason: '' })
const importCsv = ref('')
const importStatus = ref<P2B4ImportStatus | null>(null)
const importIdempotencyKey = ref('')
const importFileName = ref('')

function loadState(): Partial<{ activeTab: PlanningTab; selectedDeviceId: string; search: string; domainFilter: string; sourceFilter: string; resolutionFilter: string }> {
  try { return JSON.parse(sessionStorage.getItem(storageKey) || '{}') } catch { return {} }
}
function persistState(): void { sessionStorage.setItem(storageKey, JSON.stringify({ activeTab: activeTab.value, selectedDeviceId: selectedDeviceId.value, search: search.value, domainFilter: domainFilter.value, sourceFilter: sourceFilter.value, resolutionFilter: resolutionFilter.value })) }
watch([activeTab, selectedDeviceId, search, domainFilter, sourceFilter, resolutionFilter], persistState)
function newKey(prefix: string): string { return `${prefix}-${globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`}` }
function formatTime(ms?: number | null): string { return ms ? new Date(ms).toLocaleString('zh-CN', { hour12: false }) : '—' }
function formatValidity(from?: number | null, to?: number | null): string { return `${from ? formatTime(from) : '−∞'} → ${to ? formatTime(to) : '+∞'}` }
function sourceLabel(value: string): string { return ({ PLANNED: '规划', OBSERVED: '实测', IMPORTED: '导入', MANUAL: '人工' } as Record<string, string>)[value] || value }
function stateLabel(value: string): string { return ({ MATCH: '一致', MISMATCH: '不一致', PLANNED_ONLY: '仅规划', OBSERVED_ONLY: '仅实测', CONFLICT: '冲突', UNRESOLVED: '未解析', CONSISTENT: '一致', REVIEW_REQUIRED: '待审核', NONE: '正常' } as Record<string, string>)[value] || value }
function stateClass(value: string): string { return ['MATCH', 'CONSISTENT', 'NONE'].includes(value) ? 'good' : ['CONFLICT', 'MISMATCH'].includes(value) ? 'bad' : ['UNRESOLVED', 'REVIEW_REQUIRED', 'PLANNED_ONLY', 'OBSERVED_ONLY'].includes(value) ? 'warn' : 'neutral' }
function errorText(cause: unknown, fallback: string): string { return cause instanceof ApiRequestError ? cause.message : cause instanceof Error ? cause.message : fallback }
function resetAddressForm(): void { Object.assign(addressForm, { id: '', deviceId: selectedDeviceId.value, networkDomainId: domainFilter.value || domains.value[0]?.id || '', addressFamily: 'IPv4', normalizedAddress: '', prefixLength: 24, addressRole: 'MANAGEMENT', sourceKind: 'PLANNED', sourceReference: '', interfaceReference: '', gatewayAddress: '', vrfName: '', validFromMs: '', validToMs: '', expectedRevision: 0 }) }
function resetVlanForm(): void { Object.assign(vlanForm, { id: '', networkDomainId: domainFilter.value || domains.value[0]?.id || '', vlanId: 100, name: '', purpose: '', taggingMode: 'ACCESS', nativeVlanId: '', pvid: '100', qinQOuterId: '', qinQInnerId: '', sourceKind: 'PLANNED', sourceReference: '', validFromMs: '', validToMs: '', expectedRevision: 0 }) }
function openAddressCreate(): void { if (!writeAvailable.value) return; resetAddressForm(); addressDialog.value = true }
function openAddressEdit(row: P2B3Address): void { if (!writeAvailable.value || row.sourceKind === 'OBSERVED') return; Object.assign(addressForm, { id: row.id, deviceId: row.deviceId, networkDomainId: row.networkDomainId || '', addressFamily: row.addressFamily, normalizedAddress: row.normalizedAddress, prefixLength: row.prefixLength, addressRole: row.addressRole, sourceKind: row.sourceKind, sourceReference: row.sourceReference, interfaceReference: row.interfaceReference, gatewayAddress: row.gatewayAddress || '', vrfName: row.vrfName, validFromMs: row.validFromMs ? String(row.validFromMs) : '', validToMs: row.validToMs ? String(row.validToMs) : '', expectedRevision: row.revision }); addressDialog.value = true }
function openVlanCreate(): void { if (!writeAvailable.value) return; resetVlanForm(); vlanDialog.value = true }
function openVlanEdit(row: P2B3VlanPlan): void { if (!writeAvailable.value || row.sourceKind === 'OBSERVED') return; Object.assign(vlanForm, { id: row.id, networkDomainId: row.networkDomainId, vlanId: row.vlanId, name: row.name, purpose: row.purpose, taggingMode: row.taggingMode, nativeVlanId: row.nativeVlanId == null ? '' : String(row.nativeVlanId), pvid: row.pvid == null ? '' : String(row.pvid), qinQOuterId: row.qinQOuterId == null ? '' : String(row.qinQOuterId), qinQInnerId: row.qinQInnerId == null ? '' : String(row.qinQInnerId), sourceKind: row.sourceKind, sourceReference: row.sourceReference, validFromMs: row.validFromMs == null ? '' : String(row.validFromMs), validToMs: row.validToMs == null ? '' : String(row.validToMs), expectedRevision: row.revision }); vlanDialog.value = true }
function openMembershipCreate(): void { if (!writeAvailable.value) return; Object.assign(membershipForm, { networkDomainId: domainFilter.value || domains.value[0]?.id || '', membershipRole: 'PRIMARY', sourceKind: 'PLANNED', sourceReference: '', validFromMs: '', validToMs: '' }); membershipDialog.value = true }
function openReview(targetType: string, targetId: string, sourceKind: string, sourceReference: string, revision: number): void { Object.assign(reviewForm, { targetType, targetId, sourceKind, sourceReference, targetRevision: revision, decision: sourceKind === 'OBSERVED' ? 'ACCEPT_OBSERVED' : 'ACCEPT_PLANNED', reason: '' }); activeTab.value = 'review-import' }
async function probeCapabilities(): Promise<void> {
  const checks = await Promise.allSettled([getNetworkDomains({ limit: 1 }), getP2B4Operations(1)])
  const read = checks[0]
  readAvailable.value = read.status === 'fulfilled'
  if (!readAvailable.value) unavailableReason.value = errorText(read.status === 'rejected' ? read.reason : null, 'Schema v13 只读能力不可用')
  const write = checks[1]
  writeAvailable.value = write.status === 'fulfilled' && auth.user?.role === 'SUPERADMIN'
  if (!writeAvailable.value && readAvailable.value) unavailableReason.value = auth.user?.role === 'ADMIN' ? '当前 ADMIN 身份没有可信 Site Claims；网络规划保持只读。' : 'v14 隔离写入 gate 未开启；编辑、导入和审核按钮已禁用。'
}
async function loadDevices(): Promise<void> { try { const page = await getDeviceInventory({ page: 1, pageSize: 100 }); devices.value = page.items; if (!selectedDeviceId.value && devices.value[0]) selectedDeviceId.value = devices.value[0].id; if (selectedDeviceId.value && !devices.value.some((item) => item.id === selectedDeviceId.value)) selectedDeviceId.value = devices.value[0]?.id || '' } catch (cause) { errorMessage.value = errorText(cause, '设备列表读取失败') } }
async function loadDomains(reset = true): Promise<void> { if (!readAvailable.value) return; if (reset) domainCursor.value = undefined; const page = await getNetworkDomains({ limit: 100, cursor: domainCursor.value, search: search.value, scopeResolution: resolutionFilter.value }); domains.value = page.items; pageTotals.domains = page.total }
async function loadAddresses(reset = true): Promise<void> { if (!readAvailable.value || !selectedDeviceId.value) return; if (reset) addressCursor.value = undefined; const page = await getDeviceAddresses(selectedDeviceId.value, { limit: 100, cursor: addressCursor.value, domainId: domainFilter.value, sourceKind: sourceFilter.value }); addresses.value = page.items; pageTotals.addresses = page.total; const membershipsPage = await getDeviceMemberships(selectedDeviceId.value, { limit: 100, domainId: domainFilter.value }); memberships.value = membershipsPage.items }
async function loadVlans(reset = true): Promise<void> { if (!readAvailable.value) return; if (reset) vlanCursor.value = undefined; const page = await getVlanPlans({ limit: 100, cursor: vlanCursor.value, domainId: domainFilter.value, sourceKind: sourceFilter.value, scopeResolution: resolutionFilter.value }); vlanPlans.value = page.items; pageTotals.vlans = page.total }
async function loadDiff(): Promise<void> { if (!readAvailable.value || !selectedDeviceId.value) return; diff.value = await getNetworkDiff(selectedDeviceId.value, { domainId: domainFilter.value }) }
async function loadOperations(): Promise<void> { if (!writeAvailable.value) return; operations.value = await getP2B4Operations(100); reviews.value = await getNetworkReviews({ limit: 100 }) }
async function refresh(): Promise<void> { loading.value = true; errorMessage.value = ''; try { await probeCapabilities(); await loadDevices(); if (readAvailable.value) { await Promise.all([loadDomains(), loadAddresses(), loadVlans(), loadDiff()]) } if (writeAvailable.value) await loadOperations() } catch (cause) { errorMessage.value = errorText(cause, '网络规划数据读取失败') } finally { loading.value = false } }
async function selectTab(tab: PlanningTab): Promise<void> { activeTab.value = tab; try { if (tab === 'addresses') await loadAddresses(); if (tab === 'domains') await loadDomains(); if (tab === 'vlans') await loadVlans(); if (tab === 'diff') await loadDiff(); if (tab === 'operations' || tab === 'review-import') await loadOperations() } catch (cause) { errorMessage.value = errorText(cause, '数据读取失败') } }
async function saveAddress(): Promise<void> { if (!writeAvailable.value) return; const payload = { idempotencyKey: newKey('address'), networkDomainId: addressForm.networkDomainId, addressFamily: addressForm.addressFamily, normalizedAddress: addressForm.normalizedAddress, prefixLength: Number(addressForm.prefixLength), addressRole: addressForm.addressRole, sourceKind: addressForm.sourceKind, sourceReference: addressForm.sourceReference, interfaceReference: addressForm.interfaceReference || null, gatewayAddress: addressForm.gatewayAddress || null, vrfName: addressForm.vrfName || null, validFromMs: numberOrNull(addressForm.validFromMs), validToMs: numberOrNull(addressForm.validToMs), expectedRevision: addressForm.id ? addressForm.expectedRevision : null }; try { const result = addressForm.id ? await updateNetworkAddress(addressForm.deviceId, addressForm.id, payload) : await createNetworkAddress(addressForm.deviceId, payload); addressDialog.value = false; ElMessage.success(`地址操作已完成：${result.operationId}`); await loadAddresses(); await loadOperations() } catch (cause) { ElMessage.error(errorText(cause, '地址保存失败')) } }
async function saveMembership(): Promise<void> { if (!writeAvailable.value || !selectedDeviceId.value) return; try { const result = await createNetworkMembership(selectedDeviceId.value, { ...membershipForm, idempotencyKey: newKey('membership'), validFromMs: numberOrNull(membershipForm.validFromMs), validToMs: numberOrNull(membershipForm.validToMs) }); membershipDialog.value = false; ElMessage.success(`成员关系已保存：${result.operationId}`); await loadAddresses(); await loadOperations() } catch (cause) { ElMessage.error(errorText(cause, '成员关系保存失败')) } }
async function saveVlan(): Promise<void> { if (!writeAvailable.value) return; const payload = { idempotencyKey: newKey('vlan'), networkDomainId: vlanForm.networkDomainId, vlanId: Number(vlanForm.vlanId), name: vlanForm.name, purpose: vlanForm.purpose, taggingMode: vlanForm.taggingMode, nativeVlanId: numberOrNull(vlanForm.nativeVlanId), pvid: numberOrNull(vlanForm.pvid), qinQOuterId: numberOrNull(vlanForm.qinQOuterId), qinQInnerId: numberOrNull(vlanForm.qinQInnerId), sourceKind: vlanForm.sourceKind, sourceReference: vlanForm.sourceReference, validFromMs: numberOrNull(vlanForm.validFromMs), validToMs: numberOrNull(vlanForm.validToMs), expectedRevision: vlanForm.id ? vlanForm.expectedRevision : null, scopeResolution: 'RESOLVED' }; try { const result = vlanForm.id ? await updateVlanPlan(vlanForm.id, payload) : await createVlanPlan(payload); vlanDialog.value = false; ElMessage.success(`VLAN 操作已完成：${result.operationId}`); await loadVlans(); await loadOperations() } catch (cause) { ElMessage.error(errorText(cause, 'VLAN 保存失败')) } }
async function saveReview(): Promise<void> { if (!writeAvailable.value) return; try { const result = await createNetworkReview({ ...reviewForm, idempotencyKey: newKey('review') }); ElMessage.success(`审核记录已保存：${result.operationId}`); reviewForm.reason = ''; await loadOperations() } catch (cause) { ElMessage.error(errorText(cause, '审核记录保存失败')) } }
function onImportFile(event: Event): void { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; importFileName.value = file.name; const reader = new FileReader(); reader.onload = () => { importCsv.value = String(reader.result || ''); if (!importIdempotencyKey.value) importIdempotencyKey.value = newKey('import') }; reader.readAsText(file, 'UTF-8') }
async function previewImport(): Promise<void> { if (!writeAvailable.value || !importCsv.value.trim()) return; try { importStatus.value = await createNetworkImport({ idempotencyKey: importIdempotencyKey.value || newKey('import'), csv: importCsv.value }); importIdempotencyKey.value ||= newKey('import'); ElMessage.success('导入已完成校验，尚未写入业务表'); await loadOperations() } catch (cause) { ElMessage.error(errorText(cause, '导入预览失败')) } }
async function dryRunImport(): Promise<void> { if (!importStatus.value) return; try { importStatus.value = await dryRunNetworkImport(importStatus.value.importId); ElMessage.info('Dry-Run 已重新读取持久化预览') } catch (cause) { ElMessage.error(errorText(cause, 'Dry-Run 失败')) } }
async function confirmImport(): Promise<void> { if (!importStatus.value) return; try { importStatus.value = await confirmNetworkImport(importStatus.value.importId); ElMessage.success('导入已在单事务中提交'); await Promise.all([loadAddresses(), loadVlans(), loadDomains(), loadOperations()]) } catch (cause) { ElMessage.error(errorText(cause, '导入确认失败，业务写入已拒绝或回滚')) } }
async function cancelImport(): Promise<void> { if (!importStatus.value) return; try { importStatus.value = await cancelNetworkImport(importStatus.value.importId); ElMessage.info('导入已取消，未写入业务表'); await loadOperations() } catch (cause) { ElMessage.error(errorText(cause, '导入取消失败')) } }
async function showAddressHistory(row: P2B3Address): Promise<void> { historyLoading.value = true; historyTitle.value = `地址 ${row.normalizedAddress}/${row.prefixLength} 历史`; historyDialog.value = true; try { history.value = await getAddressHistory(row.deviceId, row.id) } catch (cause) { ElMessage.error(errorText(cause, '地址历史读取失败')) } finally { historyLoading.value = false } }
async function showVlanHistory(row: P2B3VlanPlan): Promise<void> { historyLoading.value = true; historyTitle.value = `VLAN ${row.vlanId} 历史`; historyDialog.value = true; try { history.value = await getVlanHistory(row.id) } catch (cause) { ElMessage.error(errorText(cause, 'VLAN 历史读取失败')) } finally { historyLoading.value = false } }
function numberOrNull(value: string | number): number | null { const normalized = String(value ?? '').trim(); return normalized === '' ? null : Number(normalized) }
function displayFact(fact: P2B3DiffFact): string { return `${sourceLabel(fact.sourceKind)} · ${fact.value}` }
function diffFacts(item: P2B3DiffItem): string { return [...item.planned, ...item.observed].map(displayFact).join(' | ') || '—' }
onMounted(refresh)
</script>

<template>
  <NcLayout title="网络规划管理" description="多 IP、Network Domain、VLAN 规划与实测差异；来源、版本和审核记录均来自真实隔离服务">
    <template #actions>
      <span :class="['planning-capability', writeAvailable ? 'good' : 'neutral']"><i class="status-dot" />{{ writeLabel }}</span>
      <el-button size="small" :loading="loading" @click="refresh"><el-icon><Refresh /></el-icon>刷新</el-button>
    </template>

    <div v-if="!readAvailable" class="planning-unavailable card"><el-icon><Connection /></el-icon><div><strong>网络规划只读能力不可用</strong><p>{{ unavailableReason }}</p><small>页面不会使用前端虚构数据；请先在隔离 v13/v14 服务中开启对应 gate。</small></div></div>
    <template v-else>
      <div class="planning-toolbar card">
        <label class="planning-device-picker"><span>设备</span><select v-model="selectedDeviceId" @change="loadAddresses(); loadDiff()"><option value="">请选择设备</option><option v-for="device in devices" :key="device.id" :value="device.id">{{ device.name }} · {{ device.id }}</option></select></label>
        <label class="planning-filter"><el-icon><Search /></el-icon><input v-model="search" placeholder="搜索 Network Domain" @keydown.enter="loadDomains()" /></label>
        <label class="planning-filter"><span>Domain</span><select v-model="domainFilter" @change="loadAddresses(); loadVlans(); loadDiff()"><option value="">全部域</option><option v-for="domain in domains" :key="domain.id" :value="domain.id">{{ domain.name }} · {{ domain.id }}</option></select></label>
        <label class="planning-filter"><span>来源</span><select v-model="sourceFilter" @change="loadAddresses(); loadVlans()"><option value="">全部来源</option><option value="PLANNED">规划</option><option value="OBSERVED">实测</option><option value="IMPORTED">导入</option><option value="MANUAL">人工</option></select></label>
        <label class="planning-filter"><span>Scope</span><select v-model="resolutionFilter" @change="loadDomains(); loadVlans()"><option value="">全部解析状态</option><option value="RESOLVED">已解析</option><option value="UNRESOLVED">未解析</option><option value="CONFLICT">冲突</option></select></label>
        <span class="planning-toolbar__spacer" /><span class="planning-boundary">当前设备：{{ selectedDeviceLabel }} · {{ auth.user?.role }}</span>
      </div>
      <nav class="planning-tabs" aria-label="网络规划模块">
        <button v-for="tab in [{ id: 'addresses', label: '设备地址 / 成员' }, { id: 'domains', label: 'Network Domain' }, { id: 'vlans', label: 'VLAN 规划' }, { id: 'diff', label: '规划 vs 实测' }, { id: 'review-import', label: '审核 / 导入' }, { id: 'operations', label: '操作历史' }]" :key="tab.id" :class="{ active: activeTab === tab.id }" type="button" @click="selectTab(tab.id as PlanningTab)">{{ tab.label }}</button>
      </nav>

      <section v-if="activeTab === 'addresses'" class="planning-grid planning-grid--two">
        <article class="card planning-card">
          <header class="card__header"><div><h2>多 IP 地址事实</h2><p>{{ pageTotals.addresses }} 条 · PLANNED / OBSERVED / IMPORTED / MANUAL 分离</p></div><div class="planning-actions"><el-button v-if="writeAvailable" type="primary" size="small" @click="openAddressCreate"><el-icon><Plus /></el-icon>新增地址</el-button></div></header>
          <div class="planning-table-wrap"><table class="data-table planning-table"><thead><tr><th>地址 / 族</th><th>Domain / 接口</th><th>来源 / Revision</th><th>有效期</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in addresses" :key="row.id"><td><b class="mono">{{ row.normalizedAddress }}/{{ row.prefixLength }}</b><span class="device-subline">{{ row.addressFamily }} · {{ row.addressRole }}</span></td><td><span class="mono">{{ row.networkDomainId || 'PENDING_DOMAIN' }}</span><span class="device-subline">{{ row.interfaceReference || '未指定接口' }}</span></td><td><span class="source-badge">{{ sourceLabel(row.sourceKind) }}</span><span class="device-subline mono">r{{ row.revision }} · {{ row.sourceReference }}</span></td><td class="planning-validity">{{ formatValidity(row.validFromMs, row.validToMs) }}</td><td><span :class="['state-pill', stateClass(row.effectiveState)]">{{ stateLabel(row.effectiveState) }}</span><span v-if="row.conflictState !== 'NONE'" class="device-subline warning-text">{{ row.conflictState }}</span></td><td><div class="table-actions"><el-button text size="small" @click="showAddressHistory(row)">历史</el-button><el-button text size="small" @click="openReview('ADDRESS', row.id, row.sourceKind, row.sourceReference, row.revision)">审核</el-button><el-button v-if="writeAvailable && row.sourceKind !== 'OBSERVED'" text size="small" @click="openAddressEdit(row)">编辑</el-button></div></td></tr><tr v-if="!addresses.length"><td colspan="6"><div class="empty-state"><div><el-icon><Document /></el-icon><strong>当前没有地址事实</strong><small>服务端没有返回数据；不会用示例行填充。</small></div></div></td></tr></tbody></table></div>
          <div class="planning-table-footer">显示 {{ addresses.length }} / {{ pageTotals.addresses }} 条 · <button type="button" :disabled="!addressCursor" @click="loadAddresses()">继续读取下一页</button></div>
        </article>
        <article class="card planning-card"><header class="card__header"><div><h2>设备 Domain 成员关系</h2><p>{{ memberships.length }} 条 · scope 必须显式可解析</p></div><el-button v-if="writeAvailable" type="primary" plain size="small" @click="openMembershipCreate"><el-icon><Plus /></el-icon>新增成员</el-button></header><div class="planning-table-wrap"><table class="data-table planning-table"><thead><tr><th>Domain</th><th>作用域</th><th>角色</th><th>来源 / Revision</th><th>状态</th></tr></thead><tbody><tr v-for="row in memberships" :key="row.id"><td><b>{{ row.domainName }}</b><span class="device-subline mono">{{ row.networkDomainId }}</span></td><td><span v-for="scope in row.scopes" :key="`${scope.scopeKind}-${scope.scopeReference}`" class="scope-tag">{{ scope.scopeKind }}:{{ scope.scopeReference }}</span><span v-if="!row.scopes.length" class="warning-text">{{ row.scopeResolution }}</span></td><td>{{ row.membershipRole }}</td><td><span class="source-badge">{{ sourceLabel(row.sourceKind) }}</span><span class="device-subline mono">r{{ row.revision }} · {{ row.sourceReference }}</span></td><td><span :class="['state-pill', stateClass(row.conflictState)]">{{ stateLabel(row.conflictState) }}</span></td></tr><tr v-if="!memberships.length"><td colspan="5"><div class="empty-state"><div><el-icon><Document /></el-icon><strong>当前设备没有成员关系</strong><small>请从真实 v13 database 读取或在隔离写入 gate 下新增。</small></div></div></td></tr></tbody></table></div></article>
      </section>

      <section v-else-if="activeTab === 'domains'" class="card planning-card"><header class="card__header"><div><h2>Network Domain</h2><p>{{ pageTotals.domains }} 条 · Site / Station / Line / Section 显式 scope</p></div></header><div class="planning-table-wrap"><table class="data-table planning-table"><thead><tr><th>域</th><th>类型 / VRF</th><th>Scope</th><th>来源 / Revision</th><th>生命周期</th><th>授权状态</th></tr></thead><tbody><tr v-for="row in domains" :key="row.id"><td><b>{{ row.name }}</b><span class="device-subline mono">{{ row.id }}<span v-if="row.parentDomainId"> · parent {{ row.parentDomainId }}</span></span></td><td>{{ row.domainKind }}<span class="device-subline">{{ row.vrfName || '—' }}</span></td><td><span v-for="scope in row.scopes" :key="`${scope.scopeKind}-${scope.scopeReference}`" class="scope-tag">{{ scope.scopeKind }}:{{ scope.scopeReference }}</span><span v-if="!row.scopes.length" class="warning-text">无显式 scope</span></td><td><span class="source-badge">{{ sourceLabel(row.sourceKind) }}</span><span class="device-subline mono">r{{ row.revision }} · {{ row.sourceReference }}</span></td><td>{{ row.lifecycle }} · {{ row.scopeResolution }}</td><td><span :class="['state-pill', stateClass(row.authorizationState)]">{{ row.authorizationState }}</span></td></tr><tr v-if="!domains.length"><td colspan="6"><div class="empty-state"><div><el-icon><Document /></el-icon><strong>没有符合条件的 Network Domain</strong><small>调整筛选后重新读取服务端分页结果。</small></div></div></td></tr></tbody></table></div></section>

      <section v-else-if="activeTab === 'vlans'" class="card planning-card"><header class="card__header"><div><h2>VLAN 规划</h2><p>{{ pageTotals.vlans }} 条 · 半开有效期 · planned / observed 不覆盖</p></div><el-button v-if="writeAvailable" type="primary" size="small" @click="openVlanCreate"><el-icon><Plus /></el-icon>新增 VLAN</el-button></header><div class="planning-table-wrap"><table class="data-table planning-table"><thead><tr><th>VLAN</th><th>Domain</th><th>模式 / PVID</th><th>有效期</th><th>来源 / Revision</th><th>差异 / 操作</th></tr></thead><tbody><tr v-for="row in vlanPlans" :key="row.id"><td><b>{{ row.vlanId }}</b><span class="device-subline">{{ row.name || '未命名' }} · {{ row.purpose || '无用途' }}</span></td><td class="mono">{{ row.networkDomainId }}</td><td>{{ row.taggingMode }}<span class="device-subline">PVID {{ row.pvid ?? '—' }} · Native {{ row.nativeVlanId ?? '—' }}</span></td><td class="planning-validity">{{ formatValidity(row.validFromMs, row.validToMs) }}</td><td><span class="source-badge">{{ sourceLabel(row.sourceKind) }}</span><span class="device-subline mono">r{{ row.revision }} · {{ row.sourceReference }}</span></td><td><span :class="['state-pill', stateClass(row.conflictState)]">{{ stateLabel(row.conflictState) }}</span><div class="table-actions"><el-button text size="small" @click="showVlanHistory(row)">历史</el-button><el-button text size="small" @click="openReview('VLAN_PLAN', row.id, row.sourceKind, row.sourceReference, row.revision)">审核</el-button><el-button v-if="writeAvailable && row.sourceKind !== 'OBSERVED'" text size="small" @click="openVlanEdit(row)">编辑</el-button></div></td></tr><tr v-if="!vlanPlans.length"><td colspan="6"><div class="empty-state"><div><el-icon><Document /></el-icon><strong>当前没有 VLAN 规划</strong><small>观测事实不会被前端伪造成规划。</small></div></div></td></tr></tbody></table></div></section>

      <section v-else-if="activeTab === 'diff'" class="planning-card"><div class="planning-section-head"><div><h2>规划 vs 实测</h2><p>{{ selectedDeviceLabel }} · 不一致、仅规划和仅实测均保持来源可追踪</p></div><el-button size="small" :loading="loading" @click="loadDiff"><el-icon><Refresh /></el-icon>刷新差异</el-button></div><div v-if="diff?.truncated" class="data-quality-note"><el-icon><Warning /></el-icon>部分 group 超过安全返回上限；服务端不会把 incomplete 事实误报为一致或仅规划。</div><div class="diff-grid"><article class="card diff-panel"><header class="card__header"><h3>地址差异</h3><span>{{ diff?.addressItems.length || 0 }} 组</span></header><div v-for="item in diff?.addressItems || []" :key="item.key" class="diff-item"><div class="diff-item__head"><b class="mono">{{ item.key }}</b><span :class="['state-pill', stateClass(item.status)]">{{ stateLabel(item.status) }}</span></div><p>{{ diffFacts(item) }}</p><small v-if="item.effectiveSourceReference">有效来源：{{ item.effectiveSourceKind }} · {{ item.effectiveSourceReference }}</small></div><div v-if="!diff?.addressItems.length" class="empty-state"><div><el-icon><Check /></el-icon><strong>没有地址差异组</strong><small>服务端返回为空，不代表设备已被虚构为合规。</small></div></div></article><article class="card diff-panel"><header class="card__header"><h3>VLAN 差异</h3><span>{{ diff?.vlanItems.length || 0 }} 组</span></header><div v-for="item in diff?.vlanItems || []" :key="item.key" class="diff-item"><div class="diff-item__head"><b class="mono">{{ item.key }}</b><span :class="['state-pill', stateClass(item.status)]">{{ stateLabel(item.status) }}</span></div><p>{{ diffFacts(item) }}</p><small v-if="item.effectiveSourceReference">有效来源：{{ item.effectiveSourceKind }} · {{ item.effectiveSourceReference }}</small></div><div v-if="!diff?.vlanItems.length" class="empty-state"><div><el-icon><Check /></el-icon><strong>没有 VLAN 差异组</strong><small>规划和观测事实会保持独立展示。</small></div></div></article></div></section>

      <section v-else-if="activeTab === 'review-import'" class="planning-grid planning-grid--two"><article class="card planning-card"><header class="card__header"><div><h2>人工审核</h2><p>审核引用精确 source reference + revision；过期版本会被拒绝。</p></div></header><div class="planning-form"><label class="form-field"><span>目标类型</span><select v-model="reviewForm.targetType"><option>ADDRESS</option><option>VLAN_PLAN</option><option>MEMBERSHIP</option><option>DOMAIN</option></select></label><label class="form-field"><span>目标 ID</span><input v-model="reviewForm.targetId" placeholder="从地址/VLAN表点击审核自动带入" /></label><label class="form-field"><span>来源类型</span><select v-model="reviewForm.sourceKind"><option>PLANNED</option><option>OBSERVED</option><option>IMPORTED</option><option>MANUAL</option></select></label><label class="form-field"><span>来源引用</span><input v-model="reviewForm.sourceReference" /></label><label class="form-field"><span>目标 Revision</span><input v-model.number="reviewForm.targetRevision" type="number" min="1" /></label><label class="form-field"><span>决定</span><select v-model="reviewForm.decision"><option>ACCEPT_PLANNED</option><option>ACCEPT_OBSERVED</option><option>REJECT</option><option>DEFER</option></select></label><label class="form-field form-field--wide"><span>理由</span><textarea v-model="reviewForm.reason" rows="3" placeholder="记录本次审核依据" /></label><div class="planning-form__actions"><el-button type="primary" :disabled="!writeAvailable || !reviewForm.targetId || !reviewForm.reason" @click="saveReview">保存审核记录</el-button><span class="muted">{{ writeAvailable ? '写入 v14 network_reviews；不修改 source facts' : '隔离写入 gate 未开启' }}</span></div></div><div class="review-history"><h3>最近审核记录</h3><div v-for="review in reviews" :key="review.id" class="review-row"><span class="state-pill info">{{ review.decision }}</span><b class="mono">{{ review.targetType }} · {{ review.targetId }}</b><span>r{{ review.targetRevision }} · {{ review.sourceReference }}</span><small>{{ formatTime(review.createdMs) }} · {{ review.reason }}</small></div><div v-if="!reviews.length" class="muted">暂无真实审核记录</div></div></article><article class="card planning-card"><header class="card__header"><div><h2>CSV 导入工作台</h2><p>上传 → 校验 → Dry-Run → Preview → Confirm / Cancel；不会上传即写入。</p></div><label class="file-button"><el-icon><Upload /></el-icon>选择 UTF-8 CSV<input type="file" accept=".csv,text/csv" hidden @change="onImportFile" /></label></header><div class="planning-form"><label class="form-field form-field--wide"><span>CSV 内容 {{ importFileName ? `· ${importFileName}` : '' }}</span><textarea v-model="importCsv" rows="9" placeholder="entityType,targetId,deviceId,networkDomainId,..." /></label><label class="form-field form-field--wide"><span>幂等键</span><input v-model="importIdempotencyKey" placeholder="同一 payload 重试必须复用" /></label><div class="planning-form__actions"><el-button type="primary" :disabled="!writeAvailable || !importCsv.trim()" @click="previewImport">生成 Preview</el-button><el-button :disabled="!importStatus" @click="dryRunImport">Dry-Run</el-button><el-button type="success" :disabled="!importStatus || importStatus.state !== 'PREVIEWED'" @click="confirmImport">明确 Confirm</el-button><el-button type="warning" :disabled="!importStatus || ['SUCCEEDED', 'CANCELLED'].includes(importStatus.state)" @click="cancelImport">Cancel</el-button></div></div><div v-if="importStatus" class="import-status"><div class="inventory-summary"><span class="summary-chip"><b>{{ importStatus.rowCount }}</b> 行</span><span class="summary-chip summary-chip--success"><b>{{ importStatus.validCount }}</b> 有效</span><span class="summary-chip"><b>{{ importStatus.state }}</b> 状态</span></div><p class="muted">Import ID：<span class="mono">{{ importStatus.importId }}</span> · Operation：<span class="mono">{{ importStatus.operationId }}</span></p><ul v-if="importStatus.errors.length" class="error-list"><li v-for="error in importStatus.errors" :key="error">{{ error }}</li></ul></div></article></section>

      <section v-else class="planning-grid planning-grid--two"><article class="card planning-card"><header class="card__header"><div><h2>Operation 状态</h2><p>只展示 v14 持久化 operation；刷新后重新从服务端读取。</p></div><el-button size="small" @click="loadOperations"><el-icon><Refresh /></el-icon>刷新</el-button></header><div class="planning-table-wrap"><table class="data-table planning-table"><thead><tr><th>时间</th><th>类型</th><th>状态</th><th>Operation ID</th><th>进度</th></tr></thead><tbody><tr v-for="operation in operations" :key="operation.id"><td>{{ formatTime(operation.updatedMs) }}</td><td>{{ operation.kind }}</td><td><span :class="['state-pill', stateClass(operation.state)]">{{ operation.state }}</span></td><td class="mono">{{ operation.id }}</td><td class="mono">{{ JSON.stringify(operation.progress) }}</td></tr><tr v-if="!operations.length"><td colspan="5"><div class="empty-state"><div><el-icon><Clock /></el-icon><strong>暂无操作历史</strong><small>只有真实 Preview/Confirm/Write 操作才会出现在这里。</small></div></div></td></tr></tbody></table></div></article><article class="card planning-card"><header class="card__header"><div><h2>历史读取</h2><p>地址/VLAN 修改前快照按 revision 保存。</p></div></header><div class="history-panel"><div v-if="historyLoading" class="muted">正在读取历史…</div><div v-else-if="!history.length" class="muted">请在地址或 VLAN 页点击“历史”；没有快照时如实显示为空。</div><div v-for="item in history" :key="`${item.targetId}-${item.revision}`" class="history-row"><span class="state-pill info">Revision {{ item.revision }}</span><span>{{ formatTime(item.archivedMs) }}</span><code>{{ item.snapshotJson }}</code></div></div></article></section>
    </template>

    <el-dialog v-model="addressDialog" :title="addressForm.id ? '编辑地址事实' : '新增地址事实'" width="760px"><div class="planning-form planning-form--dialog"><label class="form-field"><span>设备</span><input :value="selectedDeviceLabel" disabled /></label><label class="form-field"><span>Network Domain</span><select v-model="addressForm.networkDomainId"><option value="">请选择已解析域</option><option v-for="domain in domains.filter((item) => item.scopeResolution === 'RESOLVED' && item.lifecycle === 'ACTIVE')" :key="domain.id" :value="domain.id">{{ domain.name }} · {{ domain.id }}</option></select></label><label class="form-field"><span>地址族</span><select v-model="addressForm.addressFamily"><option>IPv4</option><option>IPv6</option></select></label><label class="form-field"><span>地址</span><input v-model="addressForm.normalizedAddress" placeholder="192.0.2.10" /></label><label class="form-field"><span>Prefix</span><input v-model.number="addressForm.prefixLength" type="number" min="0" max="128" /></label><label class="form-field"><span>角色</span><input v-model="addressForm.addressRole" /></label><label class="form-field"><span>来源</span><select v-model="addressForm.sourceKind"><option>PLANNED</option><option>IMPORTED</option><option>MANUAL</option></select></label><label class="form-field"><span>Source Reference</span><input v-model="addressForm.sourceReference" /></label><label class="form-field"><span>接口</span><input v-model="addressForm.interfaceReference" /></label><label class="form-field"><span>网关</span><input v-model="addressForm.gatewayAddress" /></label><label class="form-field"><span>VRF</span><input v-model="addressForm.vrfName" /></label><label class="form-field"><span>Valid From ms</span><input v-model="addressForm.validFromMs" type="number" /></label><label class="form-field"><span>Valid To ms</span><input v-model="addressForm.validToMs" type="number" /></label><div v-if="addressForm.id" class="planning-form__notice">Expected Revision：{{ addressForm.expectedRevision }}。Observed source 不允许覆盖，source identity 不能替换。</div></div><template #footer><el-button @click="addressDialog = false">取消</el-button><el-button type="primary" @click="saveAddress">保存</el-button></template></el-dialog>
    <el-dialog v-model="membershipDialog" title="新增 Domain 成员关系" width="560px"><div class="planning-form planning-form--dialog"><label class="form-field"><span>Network Domain</span><select v-model="membershipForm.networkDomainId"><option value="">请选择已解析域</option><option v-for="domain in domains.filter((item) => item.scopeResolution === 'RESOLVED' && item.lifecycle === 'ACTIVE')" :key="domain.id" :value="domain.id">{{ domain.name }} · {{ domain.id }}</option></select></label><label class="form-field"><span>成员角色</span><select v-model="membershipForm.membershipRole"><option>PRIMARY</option><option>SECONDARY</option><option>SHARED</option><option>OTHER</option></select></label><label class="form-field"><span>来源</span><select v-model="membershipForm.sourceKind"><option>PLANNED</option><option>IMPORTED</option><option>MANUAL</option></select></label><label class="form-field"><span>Source Reference</span><input v-model="membershipForm.sourceReference" /></label><label class="form-field"><span>Valid From ms</span><input v-model="membershipForm.validFromMs" type="number" /></label><label class="form-field"><span>Valid To ms</span><input v-model="membershipForm.validToMs" type="number" /></label></div><template #footer><el-button @click="membershipDialog = false">取消</el-button><el-button type="primary" @click="saveMembership">保存成员关系</el-button></template></el-dialog>
    <el-dialog v-model="vlanDialog" :title="vlanForm.id ? '编辑 VLAN 规划' : '新增 VLAN 规划'" width="760px"><div class="planning-form planning-form--dialog"><label class="form-field"><span>Network Domain</span><select v-model="vlanForm.networkDomainId"><option value="">请选择已解析域</option><option v-for="domain in domains.filter((item) => item.scopeResolution === 'RESOLVED' && item.lifecycle === 'ACTIVE')" :key="domain.id" :value="domain.id">{{ domain.name }} · {{ domain.id }}</option></select></label><label class="form-field"><span>VLAN ID</span><input v-model.number="vlanForm.vlanId" type="number" min="1" max="4094" /></label><label class="form-field"><span>名称</span><input v-model="vlanForm.name" /></label><label class="form-field"><span>用途</span><input v-model="vlanForm.purpose" /></label><label class="form-field"><span>Tagging Mode</span><select v-model="vlanForm.taggingMode"><option>ACCESS</option><option>TRUNK</option><option>HYBRID</option><option>QINQ</option></select></label><label class="form-field"><span>PVID</span><input v-model="vlanForm.pvid" type="number" /></label><label class="form-field"><span>Native VLAN</span><input v-model="vlanForm.nativeVlanId" type="number" /></label><label class="form-field"><span>QinQ Outer</span><input v-model="vlanForm.qinQOuterId" type="number" /></label><label class="form-field"><span>QinQ Inner</span><input v-model="vlanForm.qinQInnerId" type="number" /></label><label class="form-field"><span>来源</span><select v-model="vlanForm.sourceKind"><option>PLANNED</option><option>IMPORTED</option><option>MANUAL</option></select></label><label class="form-field"><span>Source Reference</span><input v-model="vlanForm.sourceReference" /></label><label class="form-field"><span>Valid From ms</span><input v-model="vlanForm.validFromMs" type="number" /></label><label class="form-field"><span>Valid To ms</span><input v-model="vlanForm.validToMs" type="number" /></label><div v-if="vlanForm.id" class="planning-form__notice">Expected Revision：{{ vlanForm.expectedRevision }}。同域同 VLAN 重叠区间会被服务端拒绝。</div></div><template #footer><el-button @click="vlanDialog = false">取消</el-button><el-button type="primary" @click="saveVlan">保存 VLAN 规划</el-button></template></el-dialog>
    <el-dialog v-model="historyDialog" :title="historyTitle" width="900px"><div v-if="historyLoading" class="muted">正在读取历史…</div><div v-else-if="!history.length" class="empty-state"><strong>暂无历史快照</strong></div><div v-for="item in history" :key="`${item.targetId}-${item.revision}`" class="history-row"><span class="state-pill info">Revision {{ item.revision }}</span><span>{{ formatTime(item.archivedMs) }}</span><code>{{ item.snapshotJson }}</code></div></el-dialog>
  </NcLayout>
</template>
